// Generate two small-magnitude integers to avoid signed overflow per C rules
// We constrain a and b to [-10000, 10000], so their sum is in [-20000, 20000],
// which fits within any conforming signed int implementation (minimum 16 bits).
int a = (int)(*FUZZ_PARAM(unsigned int) % 20001) - 10000;
int b = (int)(*FUZZ_PARAM(unsigned int) % 20001) - 10000;

// Invoke the target function
int result = kyanos_add(a, b);

// Property-based check: result must equal mathematical sum
long long expected = (long long)a + (long long)b; // computed in wider type to avoid UB
FUZZ_ASSERT(result == (int)expected, "kyanos_add must equal a+b within safe range");

// No persistent objects to output; result is ephemeral and intentionally not stored
